  ('8fd45ef2-ec22-5f1f-a7f9-030573ac3dc6', null, (select id from public.skills where slug = 'read-g9-word-parts'), null, 'easy',
   $q$The prefix sub- can mean "near" or "below," and the Latin root urb means "city." What are "suburban neighborhoods"?$q$, $q$[{"text":"Residential areas at the outer edge of a town","is_correct":true},{"text":"Busy business areas in the center of downtown","is_correct":false,"misconception_token":"opposite-meaning"},{"text":"Underground tunnels that run below the streets","is_correct":false,"misconception_token":"literal-reading"},{"text":"Farm areas far out in the open countryside","is_correct":false,"misconception_token":"too-broad-context"}]$q$::jsonb, $q$Residential areas at the outer edge of a town$q$, $q$Sub- plus urb means "near the city," and the passage places these homes "on the edge of town." Underground tunnels read sub- only as "under" and ignore the context of new homes.$q$, 'draft', '8322960e-ac2d-515a-aa45-ae32e3bdf95f')
